          "Prove furry superiority"
        ],
        "strategies": [
          "Balance warlike clans",
          "Use espionage, sabotage, and magic"
        ]
      }
    },
    "christian_union": {
      "ruler": "Augustine IV the Blessed",
      "appearance": {
        "features": "Silver hair, blue eyes, white robes, divine amulet"
      },
      "personality": "Fanatical faith, seemingly merciful, strategic",
      "abilities": [
        "Healing blessings",
        "Flaming Wrath (holy fire)"
      ],
      "politics": {
        "goals": [
          "Spread the true faith",
          "Destroy or convert Ottoman Empire"
        ],
        "alliances": [
          "Kings and dukes (with internal conflicts)",
          "Secret war against heretics"
        ]
      }
    },
    "conflict": {
      "summary": "Rahzaar I and Augustine IV are ideological and political rivals, destined to clash in a world-altering conflict."
    }
  }
